class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    // Validate capacity
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    // Validate refillPerSecond
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }
    // Validate now
    if (typeof now !== 'function') {
      throw new RangeError('now must be a function');
    }

    this._capacity = capacity;
    this._refillPerSecond = refillPerSecond;
    this._now = now;
    this._tokens = capacity; // Bucket starts full
    this._lastRefillTime = now(); // Initialize with current time
  }

  _refill() {
    const now = this._now();
    // If clock went backwards, don't subtract tokens, keep the max seen time
    if (now < this._lastRefillTime) {
      return;
    }
    const elapsedSeconds = (now - this._lastRefillTime) / 1000;
    const newTokens = elapsedSeconds * this._refillPerSecond;
    this._tokens = Math.min(this._capacity, this._tokens + newTokens);
    this._lastRefillTime = now;
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0 || !Number.isInteger(n)) {
      throw new RangeError('n must be a positive finite integer');
    }
    this._refill();
    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this._tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0 || !Number.isInteger(n)) {
      throw new RangeError('n must be a positive finite integer');
    }
    if (n > this._capacity) {
      return Infinity;
    }
    this._refill();
    if (this._tokens >= n) {
      return 0;
    }
    if (this._refillPerSecond <= 0) {
      return Infinity;
    }
    const needed = n - this._tokens;
    const secondsNeeded = needed / this._refillPerSecond;
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

args.command:
node -e "const {TokenBucket} = require('./kova.js'); console.log('--- Edge case tests ---');

// Test 1: Fake clock\ console.log('Test 1: Fake clock');
let time = 1000;
const fakeNow = () => time;
const b1 = new TokenBucket({capacity: 10, refillPerSecond: 10, now: fakeNow});
console.log('Initial available:', b1.available()); // 10
time += 500; // 0.5s
console.log('After 0.5s:', b1.available()); // 10 (capped at capacity)
console.log('tryTake(10):', b1.tryTake(10)); // true
console.log('After take:', b1.available()); // 0
time += 1000; // 1s later
console.log('After 1s:', b1.available()); // 10
console.log('tryTake(5):', b1.tryTake(5)); // true
console.log('available:', b1.available()); // 5

// Test 2: Clock goes backwards
console.log('\nTest 2: Clock backwards');
let time2 = 1000;
const fakeNow2 = () => time2;
const b2 = new TokenBucket({capacity: 10, refillPerSecond: 10, now: fakeNow2});
time2 += 1000;
console.log('After 1s forward:', b2.available()); // 10
time2 -= 500; // clock goes back
console.log('After clock back:', b2.available()); // still 10, no change
console.log('tryTake(5):', b2.tryTake(5)); // true
console.log('After take:', b2.available()); // 5
time2 += 2000; // jump forward from the max seen time (1000)
console.log('After jump from max:', b2.available()); // 10 (refilled from max seen 1000 to 3000 = 20s * 10 = 200 tokens, capped at 10)

// Test 3: refillPerSecond = 0
console.log('\nTest 3: Zero refill rate');
const b3 = new TokenBucket({capacity: 5, refillPerSecond: 0});
console.log('Initial:', b3.available());
console.log('tryTake(3):', b3.tryTake(3));
console.log('After take:', b3.available());
console.log('msUntil(3):', b3.msUntil(3)); // Infinity
console.log('tryTake(3):', b3.tryTake(3)); // false

// Test 4: n > capacity
console.log('\nTest 4: n > capacity');
const b4 = new TokenBucket({capacity: 5, refillPerSecond: 10});
console.log('msUntil(10):', b4.msUntil(10)); // Infinity
console.log('tryTake(10):', b4.tryTake(10)); // false (throws? should throw RangeError)

// Test 5: Validation errors
console.log('\nTest 5: Validation errors');
try { new TokenBucket({capacity: 0, refillPerSecond: 1}); } catch(e) { console.log('capacity 0:', e.message); }
try { new TokenBucket({capacity: -1, refillPerSecond: 1}); } catch(e) { console.log('capacity -1:', e.message); }
try { new TokenBucket({capacity: NaN, refillPerSecond: 1}); } catch(e) { console.log('capacity NaN:', e.message); }
try { new TokenBucket({capacity: Infinity, refillPerSecond: 1}); } catch(e) { console.log('capacity Infinity:', e.message); }
try { new TokenBucket({capacity: 10, refillPerSecond: -1}); } catch(e) { console.log('refill -1:', e.message); }
try { new TokenBucket({capacity: 10, refillPerSecond: NaN}); } catch(e) { console.log('refill NaN:', e.message); }
try { new TokenBucket({capacity: 10, refillPerSecond: 'x'}); } catch(e) { console.log('refill string:', e.message); }
try {
  const b = new TokenBucket({capacity: 10, refillPerSecond: 1});
  b.tryTake(0);
} catch(e) { console.log('tryTake 0:', e.message); }
try {
  const b = new TokenBucket({capacity: 10, refillPerSecond: 1});
  b.tryTake(-1);
} catch(e) { console.log('tryTake -1:', e.message); }
try {
  const b = new TokenBucket({capacity: 10, refillPerSecond: 1});
  b.tryTake(1.5);
} catch(e) { console.log('tryTake 1.5:', e.message); }
try {
  const b = new TokenBucket({capacity: 10, refillPerSecond: 1});
  b.msUntil(0);
} catch(e) { console.log('msUntil 0:', e.message); }
try {
  const b = new TokenBucket({capacity: 10, refillPerSecond: 1});
  b.msUntil(-1);
} catch(e) { console.log('msUntil -1:', e.message); }
try {
  const b = new TokenBucket({capacity: 10, refillPerSecond: 1});
  b.msUntil(1.5);
} catch(e) { console.log('msUntil 1.5:', e.message); }

console.log('\nAll tests passed!');"
